mapper.select:
select ac.seq, ac.name, ac.login_id, ac.lang, '****-'||substr(ac.birth,6) as birth, ac.gender, ts.disease, ac.user_type_cd, (select val from sys_code_det a where a.code = 'USER_TYPE_CD' and a.cd = ac.user_type_cd and a.use_yn = 'Y') as user_type_nm, ( select sum(ccc.progress) / (select sum(json_array_length(x.value::json)) from (SELECT DISTINCT t.value FROM jsonb_each((SELECT ts.data FROM track_service ts where ts.is_enabled and ts.status = 'ACTIVE' AND ts.account_seq = ac.seq and ts.hospital_seq = (select hospital_seq from cm_doctor where seq = #{dSeq}))) as t(key,value)) as x) from cm_contents_check ccc where ccc.contents_seq in ( select json_array_elements_text(t.value::json)::bigint as contents from jsonb_each((SELECT ts.data FROM track_service ts where ts.is_enabled and ts.status = 'ACTIVE' AND ts.account_seq = ac.seq and ts.hospital_seq = (select hospital_seq from cm_doctor where seq = #{dSeq}))) as t(key,value)) and ccc.account_seq = ac.seq and ccc.is_enabled and ccc.track_service_seq = (SELECT ts.seq FROM track_service ts where ts.is_enabled and ts.status = 'ACTIVE' AND ts.account_seq = ac.seq and ts.hospital_seq = (select hospital_seq from cm_doctor where seq = #{dSeq})) ) as progress, to_char(cast(ts.created_at at time zone 'kst' AS timestamp), 'YYYY-MM-DD HH24:MI:SS') as createdAt from (select * from track_service where is_enabled and status = 'ACTIVE' and hospital_seq = (select hospital_seq from cm_doctor where seq = #{dSeq}) ) ts right join (select * from account where is_enabled and is_dropped = false and lang = #{lang}) ac on ac.seq = ts.account_seq
AND ac.name ILIKE CONCAT('%', #{searchText}, '%')
ORDER BY ac.seq DESC LIMIT #{pagination.endNum} OFFSET #{pagination.startNum}

mapper.delete:
		delete 
		  from coaching_user_answer_info
         where 1=1
 		   and account_seq = #{acSeq}
 		   and account_seq in (select account_seq
 		                        from hospital_service
 		                       where hospital_seq = (select hospital_seq from cm_doctor where seq = #{dSeq})
 		                      )

		  and category_cd = #{categoryCd}


	      and step_day_cd >= #{stepDayCd}


		  and progress_type_cd = #{progressTypeCd}

mapper.update:
update account
   set user_type_cd = #{userTypeCd}
      , updated_at = now()
 where seq = #{seq}

mapper.select:
select to_char(a.created_at ,'yyyy-mm-dd HH24:MI:SS') as search_dt ,b.name ,a.cancer_type ,(select aa.val from sys_code_det aa where aa.code = 'DISEASE_CD' and aa.cd = a.cancer_type and aa.use_yn = 'Y') as cancer_type_nm ,a.search_text from account_search_history a ,account b where 1=1 and a.account_seq = b.seq
and to_char(a.created_at ,'yyyymm') = #{yyyymm}
and b.name = #{name}
order by to_char(a.created_at ,'yyyy-mm-dd HH24:MI:SS') desc

        select a.contents_seq, cc.title, cc.contents , a.cnt
          from (
        		select ccf.contents_seq , count(*) as cnt
		          from cm_contents_favorite ccf 
		         group by ccf.contents_seq
		        ) a
	          , cm_contents cc 
         where a.contents_seq  = cc.seq 
           and cc.lang = #{lang}
         order by a.cnt desc
